contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        c.Put{value: amount}(unlockTime);
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint minSum = c.MinSum();

        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }

