contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        c.Put{value: amount}(unlockTime);
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint minSum = c.MinSum();

        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // Save arithmetic to avoid underflow inside assert.
        uint expectedBalSuccess;
        if (!reverted) {
            expectedBalSuccess = beforeBal - amount;
        }

        bool canSucceed = beforeBal >= minSum && beforeBal >= amount && block.timestamp > beforeUnlock;

        assert(reverted || (canSucceed && afterBal == expectedBalSuccess) || (!canSucceed && afterBal == beforeBal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint unlockTime, uint amount) public payable {
        // Use a fixed deposit that is at least the amount but not dependent on msg.value
        uint deposit = amount + 1 ether;
        require(address(this).balance >= deposit, "insufficient test balance for deposit");

        c.Put{value: deposit}(unlockTime);
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint minSum = c.MinSum();

        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // If Collect succeeds, the caller's balance must not increase (it may decrease) and
        // the contract's balance cannot be made larger than the original deposit.
        // If Collect reverts, the caller's balance must remain exactly the same.
        assert(
            reverted ? (afterBal == beforeBal) : (afterBal <= beforeBal)
        );
    }

    receive() external payable {}
}

