contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 putAmount, uint256 unlockTime, uint256 collectAmount) public payable {
        require(address(this).balance >= putAmount);
        require(putAmount > 0);

        // Deposit so msg.sender (this test contract) has a Holder entry.
        c.Put{value: putAmount}(unlockTime);

        (uint256 balBefore, uint256 unlockBefore) = c.Acc(address(this));
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 balAfter, ) = c.Acc(address(this));
        uint256 cBalAfter = address(c).balance;

        // The call can only succeed if the deposit met the contract's minimum sum,
        // the requested amount does not exceed the caller's balance, and the lock
        // has expired.
        bool shouldSucceed = (balBefore >= c.MinSum()) && (balBefore >= collectAmount) && (block.timestamp > unlockBefore);

        assert(reverted == !shouldSucceed);
        assert(!reverted ==> (balAfter == balBefore - collectAmount));
        assert(!reverted ==> (cBalAfter == cBalBefore - collectAmount));
    }

    receive() external payable {}
}

