contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        // Fresh C: caller (this test contract) has no Acc entry yet, so its
        // unlockTime and balance are both zero before the first Put.

        require(putAmount >= 0);
        require(collectAmount >= 0);
        require(address(this).balance >= putAmount);

        c.Put{value: putAmount}(unlockTime);

        uint minSum = c.MinSum();
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        // A failing call must not have changed anything observable about the caller's
        // Acc entry or about the Ether held by c.
        assert(
            reverted
                ? (afterUnlockTime == beforeUnlockTime && afterBalance == beforeBalance && cBalanceAfter == cBalanceBefore)
                : true
        );

        // A successful call is allowed only when the caller's recorded balance is at
        // least MinSum, at least the requested amount, and the unlock time has passed;
        // in that case it must transfer exactly the requested amount out of c and out
        // of the caller's recorded balance.
        if (!reverted) {
            assert(beforeBalance >= minSum);
            assert(beforeBalance >= collectAmount);
            assert(block.timestamp > beforeUnlockTime);
            assert(afterBalance == beforeBalance - collectAmount);
            assert(cBalanceAfter == cBalanceBefore - collectAmount);
        }
    }

    receive() external payable {}

    fallback() external payable {}
}

